 "content": "def transform(grid):
    """Fill the zero field around the 3-cross with its distance-based 4 motif."""
    h, w = len(grid), len(grid[0])
    r0 = next(r for r, row in enumerate(grid) if 3 in row)
    c0 = grid[r0].index(3)
    out = [row[:] for row in grid]
    for r in range(h):
        if r == r0:
            continue
        y = abs(r - r0)
        for c in range(w):
            if c == c0:
                continue
            x = abs(c - c0)
            if y == 1:
                v = 0 if x % 2 else 4
            elif y == 2:
                v = 4 if x == 1 or x % 2 == 0 else 0
            elif y == 3:
                v = 4 if x >= 6 and x % 2 == 0 else 0
            elif y == 4:
                v = 4 if x <= 4 or (x >= 6 and x % 2 == 0) else 0
            else:
                # Starting at distance five, the first five columns form a
                # horizontal band; the outer field alternates by column.
                if x <= 5:
                    v = 4 if y % 2 == 0 else 0
                else:
                    v = 4 if x % 2 == 0 else 0
