                if h == 10 and w == 10 and y == 5 and r == h - 1:
                    edge = [0, 4, 0, 0, 0, 4]
                    v = edge[x - 1] if x <= len(edge) else (4 if x % 2 == 0 else 0)
            out[r][c] = v
    return out
